--
-- Table structure for table `device_op_status_log`
--

DROP TABLE IF EXISTS `device_op_status_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `device_op_status_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'UUID',
  `comm_status` int(11) NOT NULL COMMENT '同ems通訊狀態, 0:正常 1:異常 ',
  `created_by` varchar(255) DEFAULT NULL COMMENT '新增此筆資料的模組',
  `data_time` datetime NOT NULL COMMENT '記錄時間 ',
  `device_name` varchar(40) NOT NULL COMMENT '設備名稱',
  `direction` varchar(1) DEFAULT NULL COMMENT '方向（N=北上，S=南下，E=東向，W=西向）',
  `discontinued_time` datetime DEFAULT NULL COMMENT '預設下架時間',
  `display` varchar(500) DEFAULT NULL COMMENT '現場顯示內容 ',
  `line_id` varchar(20) DEFAULT NULL COMMENT '路線編號（屬於哪一個國道）',
  `location` varchar(20) DEFAULT NULL COMMENT 'F=高速公路，H=快速道路，T=隧道，R=匝道，P=保留 (程度表的key)S=服務區，L=地方道路',
  `mileage` int(11) DEFAULT NULL COMMENT '里程數（公尺）',
  `op_status_hi_nibble` varchar(255) DEFAULT NULL COMMENT 'opStatus bit4~bit7',
  `op_status_low_nibble` varchar(255) DEFAULT NULL COMMENT 'opStatus bit0~bit3',
  `operation_result` varchar(255) DEFAULT NULL COMMENT '操作結果',
  `priority_type` varchar(255) DEFAULT NULL COMMENT '顯示優先權的設計  強制手動 > 反應計畫 > 一般手動 > 排程 > 自動演算',
  `user_id` varchar(255) DEFAULT NULL COMMENT '使用者 ID',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

