LOCK TABLES `device_op_status_log` WRITE;
/*!40000 ALTER TABLE `device_op_status_log` DISABLE KEYS */;
/*!40000 ALTER TABLE `device_op_status_log` ENABLE KEYS */;
UNLOCK TABLES;

