  `section_id` varchar(20) DEFAULT NULL COMMENT '路段編號',
  `show_in_ems` bit(1) DEFAULT NULL COMMENT '是否顯示於EMS中',
  `device_name` varchar(40) NOT NULL,
  PRIMARY KEY (`device_name`),
  CONSTRAINT `FKpguadslkx7forsbj2h18pgj7y` FOREIGN KEY (`device_name`) REFERENCES `device_config` (`device_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
