CREATE TABLE `hcce_group_info` (
  `group_name` varchar(50) NOT NULL COMMENT 'Cluster 群組名稱',
  `allow_active` bit(1) NOT NULL COMMENT '可否變成 Active 模式',
  `cluster_mode` int(11) NOT NULL COMMENT 'Cluster 狀態',
  `description` varchar(255) DEFAULT NULL COMMENT '說明',
  PRIMARY KEY (`group_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
