  `sum_of_rx_speed_per_sec` bigint(20) NOT NULL COMMENT '所有網路介面接收流量的總和',
  `sum_of_tx_speed_per_sec` bigint(20) NOT NULL COMMENT '所有網路介面傳輸流量的總和',
  PRIMARY KEY (`id`),
  KEY `IDX3u5n8mcgqwlbbi2xg1wdadcil` (`group_name`),
  KEY `IDXe4wuce3w16u6refeeyo3l940t` (`node_name`),
