  `mileage` int(11) DEFAULT NULL COMMENT '里程數（公尺）',
  `travel_time_visible` bit(1) DEFAULT NULL COMMENT '轄區內的切割點皆可被選為 旅行時間目的地，轄區外的切割點，其 travelTimeVisible = true 時，可被選為 旅行時間目的地',
  PRIMARY KEY (`division_id`)
