DROP TABLE IF EXISTS `road_gps`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `road_gps` (
  `no` bigint(20) NOT NULL AUTO_INCREMENT,
  `km1` double DEFAULT NULL COMMENT '公里數1',
  `km2` double DEFAULT NULL COMMENT '公里數2',
  `lat` double DEFAULT NULL COMMENT '緯度 ',
  `line_id` varchar(255) DEFAULT NULL COMMENT '路線',
  `lng` double DEFAULT NULL COMMENT '經度 ',
  PRIMARY KEY (`no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
