  `dds_road_section_group2` bit(1) DEFAULT NULL COMMENT 'DDS壅塞路段顯示設定群組二 ',
  `dds_road_section_group3` bit(1) DEFAULT NULL COMMENT 'DDS壅塞路段顯示設定群組三',
  `dds_road_section_group4` bit(1) DEFAULT NULL COMMENT 'DDS壅塞路段顯示設定群組四',
  `direction` varchar(1) DEFAULT NULL COMMENT '方向（N=北上，S=南下，E=東向，W=西向）',
  `end_division_id` varchar(20) DEFAULT NULL,
  `event_exec_mode` varchar(255) DEFAULT NULL COMMENT '反應計畫事件執行模式',
  `event_log_mode` varchar(255) DEFAULT NULL COMMENT '反應計畫事件登錄模式 ',
  `free_speed` int(11) DEFAULT NULL COMMENT '自由車速',
  `lane_count` smallint(6) NOT NULL,
  `line_id` varchar(20) NOT NULL COMMENT '路線編號（屬於哪一個路線）',
  `manual_enabled` bit(1) DEFAULT NULL COMMENT '允許手動建立事件',
  `max_speed` int(11) DEFAULT NULL,
  `min_speed` int(11) DEFAULT NULL COMMENT ' 最底限速',
  `section_flow` int(11) DEFAULT NULL COMMENT '車道容量(預設:2000,單位:PCU)',
  `section_name` varchar(40) DEFAULT NULL COMMENT '路段名稱',
  `standard_vd` varchar(20) DEFAULT NULL COMMENT '主標竿VD',
  `start_division_id` varchar(20) NOT NULL COMMENT '開始的分割點編號（系統交流道、交流道、收費站、服務區）',
  `sub_standard_vd1` varchar(20) DEFAULT NULL COMMENT '次標竿VD1',
  `sub_standard_vd2` varchar(20) DEFAULT NULL COMMENT '次標竿VD2',
  PRIMARY KEY (`section_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

